orientConflictCollider <- function(pdag, x, y, z) { ## x - y - z
  ## pdag: amat, pdag[x,y] = 1 and pdag[y,x] = 0 means x -> y
  ## x,y,z: colnumber of nodes in pdag
  ## only used if conflicts should be solved

  ## orient x - y
  if (pdag[x,y] == 1) {
    ## x --- y, x --> y => x --> y
    pdag[y,x] <- 0
  } else {
    ## x <-- y, x <-> y => x <-> y
    pdag[x,y] <- pdag[y,x] <- 2
  }

  ## orient z - y
  if (pdag[z,y] == 1) {
    ## z --- y, z --> y => z --> y
    pdag[y,z] <- 0
  } else {
    ## z <-- y, z <-> y => z <-> y
    pdag[z,y] <- pdag[y,z] <- 2
  }

  pdag
}

